-- TESTER research seeds for provider/compliance intelligence.
-- Source watches feed evidence only; evidence does not directly mutate provider authority.

on conflict(work_key) do update set
 question=excluded.question,required_evidence=excluded.required_evidence,priority=excluded.priority,
 next_action=excluded.next_action,metadata=excluded.metadata,updated_at=now();

on conflict(source_key) do update set
 work_key=excluded.work_key,source_title=excluded.source_title,source_url=excluded.source_url,
 authority_level=excluded.authority_level,status='ACTIVE',expected_signals=excluded.expected_signals,
 next_check_at=now(),metadata=excluded.metadata,updated_at=now();